using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Manages the best score across game sessions using PlayerPrefs.
/// Provides methods to get and set the best score, and to update it when a new high score is achieved.
/// </summary>
public class BestScoreManager : MonoBehaviour
{
    private const string BEST_SCORE_KEY = "BestScore";
    private int bestScore = 0;

    /// <summary>
    /// Gets the current best score, loading it from PlayerPrefs if not already loaded.
    /// </summary>
    public int BestScore
    {
        get
        {
            if (bestScore == 0)
            {
                bestScore = PlayerPrefs.GetInt(BEST_SCORE_KEY, 0);
            }
            return bestScore;
        }
    }

    /// <summary>
    /// Sets the best score and saves it to PlayerPrefs.
    /// </summary>
    /// <param name="score">The new best score to set.</param>
    public void SetBestScore(int score)
    {
        if (score > BestScore)
        {
            bestScore = score;
            PlayerPrefs.SetInt(BEST_SCORE_KEY, score);
            PlayerPrefs.Save();
        }
    }

    /// <summary>
    /// Resets the best score to zero.
    /// </summary>
    public void ResetBestScore()
    {
        bestScore = 0;
        PlayerPrefs.DeleteKey(BEST_SCORE_KEY);
        PlayerPrefs.Save();
    }
}
```

