using UnityEngine;
using TMPro;

/// <summary>
/// Shows "BEST: n" on the main menu (GDD Section 11). It sets itself up when the game starts.
/// It finds the menu canvas with UIKit.FindMenuCanvas() and adds one label to it, so no scene
/// or menu code has to change. If a scene load destroys the label, it adds the label again.
/// The label reads BestScoreManager.Best, so it updates by itself after a new best is submitted.
///
/// STILL MISSING: something has to call BestScoreManager.Submit(score) when a run ends.
/// I wasn't shown the code that ends a run and holds the score, so I couldn't add that call.
/// Until it's added, BEST stays at 0.
/// </summary>
public class BestScoreMenuLabel : MonoBehaviour
{
    private const string LabelName = "BestScoreLabel";
    private const float SearchInterval = 0.5f;

    private TextMeshProUGUI label;
    private int shown = -1;
    private float nextSearch;

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
    private static void Install()
    {
        var host = new GameObject("BestScoreMenuLabel");
        DontDestroyOnLoad(host);
        host.AddComponent<BestScoreMenuLabel>();
    }

    private void Update()
    {
        if (label == null)
        {
            if (Time.unscaledTime < nextSearch) return;
            nextSearch = Time.unscaledTime + SearchInterval;

            label = FindOrCreateLabel();
            shown = -1;
            if (label == null) return;
        }

        int best = BestScoreManager.Best;
        if (best != shown)
        {
            shown = best;
            label.text = "BEST: " + best;
        }
    }

    private static TextMeshProUGUI FindOrCreateLabel()
    {
        var canvas = UIKit.FindMenuCanvas();
        if (canvas == null) return null;

        Transform parent = canvas.transform;

        Transform existing = parent.Find(LabelName);
        if (existing != null) return existing.GetComponent<TextMeshProUGUI>();

        var go = new GameObject(LabelName, typeof(RectTransform));
        var rt = (RectTransform)go.transform;
        rt.SetParent(parent, false);

        // Same spot BestScoreManager.DrawMenuLabel planned: 20 from the left, 270 down, 200 x 30.
        rt.anchorMin = new Vector2(0f, 1f);
        rt.anchorMax = new Vector2(0f, 1f);
        rt.pivot = new Vector2(0f, 1f);
        rt.anchoredPosition = new Vector2(20f, -270f);
        rt.sizeDelta = new Vector2(200f, 30f);
        rt.SetAsLastSibling();

        var text = go.AddComponent<TextMeshProUGUI>();
        text.fontSize = 24f;
        text.color = Color.white;
        text.alignment = TextAlignmentOptions.Left;
        text.raycastTarget = false;
        text.text = "BEST: " + BestScoreManager.Best;

        return text;
    }
}
